insert into public.templates (id, category, name, description, tags, style, industry, tier_required, is_featured, thumbnail, structure) values
  ('91f5c8fa-c704-44ef-ba02-e9b326ee1c24', 'SaaS', 'Northstar', 'Run your whole operation from one clean dashboard. A modern saas site for Northstar, with 3 pages.', ARRAY['saas', 'modern']::text[], 'modern', 'saas', 'free', true, 'data:image/svg+xml;base64,', $tpl${"files":{"components/Navbar.tsx":"export default function Navbar() {\n  return (\n    <header className=\"sticky top-0 z-40 border-b border-slate-100 bg-white/80 backdrop-blur\">\n      <nav className=\"mx-auto flex max-w-6xl items-center justify-between px-6 py-4\">\n        <a href=\"/\" className=\"font-serif text-lg font-bold tracking-tight text-slate-900\">Northstar</a>\n        <div className=\"hidden items-center gap-8 md:flex\">\n        <a href=\"/pricing\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Pricing</a>\n        <a href=\"/contact\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Contact</a>\n        </div>\n        <a href=\"/contact\" className=\"rounded-full bg-indigo-600 px-4 py-2 text-sm font-semibold text-white hover:bg-indigo-700 transition-colors\">Get started</a>\n      </nav>\n    </header>\n  );\n}\n","components/Hero.tsx":"export default function Hero() {\n  return (\n    <section className=\"bg-white\">\n      <div className=\"mx-auto grid max-w-6xl items-center gap-12 px-6 py-24 md:grid-cols-2 md:py-32\">\n        <div>\n          <span className=\"inline-block rounded-full bg-indigo-100 px-3 py-1 text-xs font-semibold uppercase tracking-wider text-indigo-700\">Saas</span>\n          <h1 className=\"font-serif mt-5 text-4xl font-bold leading-tight tracking-tight text-slate-900 md:text-5xl\">Run your whole operation from one clean dashboard.</h1>\n          <p className=\"mt-5 max-w-lg text-lg text-slate-600\">Northstar replaces the spreadsheet, the sticky notes, and the six browser tabs your team juggles today.</p>\n          <div className=\"mt-8 flex flex-wrap gap-3\">\n            <a href=\"/contact\" className=\"rounded-full bg-indigo-600 px-6 py-3 text-sm font-semibold text-white hover:bg-indigo-700 transition-colors\">Get started</a>\n            <a href=\"#features\" className=\"rounded-full border border-slate-200 px-6 py-3 text-sm font-semibold text-slate-700 hover:border-slate-400 transition-colors\">View pricing</a>\n          </div>\n        </div>\n        <div className=\"aspect-[4/3] rounded-2xl bg-gradient-to-br from-indigo-100 to-indigo-50 ring-1 ring-indigo-100\" />\n      </div>\n    </section>\n  );\n}\n","components/Footer.tsx":"export default function Footer() {\n  return (\n    <footer className=\"border-t border-slate-100 bg-slate-50\">\n      <div className=\"mx-auto max-w-6xl px-6 py-14\">\n        <div className=\"grid grid-cols-2 gap-8 md:grid-cols-4\">\n          <div className=\"col-span-2 md:col-span-1\">\n            <p className=\"font-serif text-lg font-bold text-slate-900\">Northstar</p>\n            <p className=\"mt-2 max-w-xs text-sm text-slate-500\">Northstar replaces the spreadsheet, the sticky notes, and the six browser tabs your team juggles today.</p>\n          </div>\n          <div>\n            <p className=\"text-xs font-semibold uppercase tracking-wider text-slate-400\">SaaS</p>\n            <ul className=\"mt-3 space-y-2\">\n              <li><a href=\"/pricing\" className=\"text-sm text-slate-500 hover:text-slate-900\">Pricing</a></li>\n              <li><a href=\"/contact\" className=\"text-sm text-slate-500 hover:text-slate-900\">Contact</a></li>\n            </ul>\n          </div>\n          <div>\n            <p className=\"text-xs font-semibold uppercase tracking-wider text-slate-400\">Legal</p>\n            <ul className=\"mt-3 space-y-2\">\n              <li><a href=\"/\" className=\"text-sm text-slate-500 hover:text-slate-900\">Privacy</a></li>\n              <li><a href=\"/\" className=\"text-sm text-slate-500 hover:text-slate-900\">Terms</a></li>\n            </ul>\n          </div>\n        </div>\n        <div className=\"mt-12 flex flex-col items-center justify-between gap-4 border-t border-slate-200 pt-6 text-xs text-slate-400 sm:flex-row\">\n          <p>&copy; {new Date().getFullYear()} Northstar. All rights reserved.</p>\n          <div className=\"flex items-center gap-2 text-indigo-600\">\n            <span className=\"h-1.5 w-1.5 rounded-full bg-indigo-600\" /> Built with webma\n          </div>\n        </div>\n      </div>\n    </footer>\n  );\n}\n","components/ContactForm.tsx":"export default function ContactForm() {\n  return (\n    <section className=\"mx-auto max-w-2xl px-6 py-20\">\n      <h2 className=\"font-serif text-3xl font-bold tracking-tight text-slate-900\">Talk to Northstar</h2>\n      <p className=\"mt-3 text-slate-500\">We usually reply within a few hours.</p>\n      <form\n        className=\"mt-8 space-y-4\"\n        onSubmit={async (e) => {\n          e.preventDefault();\n          const form = e.currentTarget;\n          const data = Object.fromEntries(new FormData(form).entries());\n          const website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}\n      >\n        <div className=\"grid gap-4 sm:grid-cols-2\">\n          <input name=\"name\" required placeholder=\"Your name\" className=\"rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-indigo-500 focus:outline-none\" />\n          <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-indigo-500 focus:outline-none\" />\n        </div>\n        <textarea name=\"message\" required rows={4} placeholder=\"How can we help?\" className=\"w-full rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-indigo-500 focus:outline-none\" />\n        <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n        <button type=\"submit\" className=\"rounded-full bg-indigo-600 px-6 py-2.5 text-sm font-semibold text-white hover:bg-indigo-700 transition-colors\">Send message</button>\n      </form>\n    </section>\n  );\n}\n","components/Stats.tsx":"export default function Stats() {\n  return (\n    <section className=\"bg-slate-950 text-white\">\n      <div className=\"mx-auto grid max-w-6xl grid-cols-2 gap-8 px-6 py-16 text-center md:grid-cols-4\">\n          <div>\n            <p className=\"text-3xl font-bold text-indigo-300 md:text-4xl\">12k+</p>\n            <p className=\"mt-1 text-xs uppercase tracking-wider text-white/50\">Happy customers</p>\n          </div>\n          <div>\n            <p className=\"text-3xl font-bold text-indigo-300 md:text-4xl\">99.98%</p>\n            <p className=\"mt-1 text-xs uppercase tracking-wider text-white/50\">Uptime</p>\n          </div>\n          <div>\n            <p className=\"text-3xl font-bold text-indigo-300 md:text-4xl\">4.9/5</p>\n            <p className=\"mt-1 text-xs uppercase tracking-wider text-white/50\">Average rating</p>\n          </div>\n          <div>\n            <p className=\"text-3xl font-bold text-indigo-300 md:text-4xl\">40hrs</p>\n            <p className=\"mt-1 text-xs uppercase tracking-wider text-white/50\">Saved per month</p>\n          </div>\n      </div>\n    </section>\n  );\n}\n","components/Features.tsx":"import { Zap, ShieldCheck, Users, BarChart3 } from \"lucide-react\";\n\nexport default function Features() {\n  return (\n    <section id=\"features\" className=\"mx-auto max-w-6xl px-6 py-20\">\n      <div className=\"max-w-xl\">\n        <h2 className=\"font-sans text-3xl font-bold tracking-tight text-slate-900\">Everything you need, nothing you don't</h2>\n        <p className=\"mt-3 text-slate-500\">Northstar replaces the spreadsheet, the sticky notes, and the six browser tabs your team juggles today.</p>\n      </div>\n      <div className=\"mt-10 grid gap-4 sm:grid-cols-2 lg:grid-cols-3\">\n          <div className=\"rounded-2xl border border-slate-100 p-6\">\n            <div className=\"flex h-10 w-10 items-center justify-center rounded-xl bg-indigo-100 text-indigo-600\">\n              <Zap size={18} />\n            </div>\n            <h3 className=\"mt-4 font-semibold text-slate-900\">Workflow automation</h3>\n            <p className=\"mt-1.5 text-sm text-slate-500\">Cut repetitive work out of your team's day.</p>\n          </div>\n          <div className=\"rounded-2xl border border-slate-100 p-6\">\n            <div className=\"flex h-10 w-10 items-center justify-center rounded-xl bg-indigo-100 text-indigo-600\">\n              <ShieldCheck size={18} />\n            </div>\n            <h3 className=\"mt-4 font-semibold text-slate-900\">Real-time analytics</h3>\n            <p className=\"mt-1.5 text-sm text-slate-500\">Know what's working before your competitors do.</p>\n          </div>\n          <div className=\"rounded-2xl border border-slate-100 p-6\">\n            <div className=\"flex h-10 w-10 items-center justify-center rounded-xl bg-indigo-100 text-indigo-600\">\n              <Users size={18} />\n            </div>\n            <h3 className=\"mt-4 font-semibold text-slate-900\">Team workspaces</h3>\n            <p className=\"mt-1.5 text-sm text-slate-500\">Give every team its own space without losing shared context.</p>\n          </div>\n          <div className=\"rounded-2xl border border-slate-100 p-6\">\n            <div className=\"flex h-10 w-10 items-center justify-center rounded-xl bg-indigo-100 text-indigo-600\">\n              <BarChart3 size={18} />\n            </div>\n            <h3 className=\"mt-4 font-semibold text-slate-900\">API access</h3>\n            <p className=\"mt-1.5 text-sm text-slate-500\">Build on top of the platform, not around it.</p>\n          </div>\n          <div className=\"rounded-2xl border border-slate-100 p-6\">\n            <div className=\"flex h-10 w-10 items-center justify-center rounded-xl bg-indigo-100 text-indigo-600\">\n              <Zap size={18} />\n            </div>\n            <h3 className=\"mt-4 font-semibold text-slate-900\">Role-based permissions</h3>\n            <p className=\"mt-1.5 text-sm text-slate-500\">Control exactly who can see and change what.</p>\n          </div>\n          <div className=\"rounded-2xl border border-slate-100 p-6\">\n            <div className=\"flex h-10 w-10 items-center justify-center rounded-xl bg-indigo-100 text-indigo-600\">\n              <ShieldCheck size={18} />\n            </div>\n            <h3 className=\"mt-4 font-semibold text-slate-900\">Audit logs</h3>\n            <p className=\"mt-1.5 text-sm text-slate-500\">Every change tracked, every rollback one click away.</p>\n          </div>\n          <div className=\"rounded-2xl border border-slate-100 p-6\">\n            <div className=\"flex h-10 w-10 items-center justify-center rounded-xl bg-indigo-100 text-indigo-600\">\n              <Users size={18} />\n            </div>\n            <h3 className=\"mt-4 font-semibold text-slate-900\">Custom integrations</h3>\n            <p className=\"mt-1.5 text-sm text-slate-500\">Connect the tools your team already relies on.</p>\n          </div>\n          <div className=\"rounded-2xl border border-slate-100 p-6\">\n            <div className=\"flex h-10 w-10 items-center justify-center rounded-xl bg-indigo-100 text-indigo-600\">\n              <BarChart3 size={18} />\n            </div>\n            <h3 className=\"mt-4 font-semibold text-slate-900\">Enterprise-grade security</h3>\n            <p className=\"mt-1.5 text-sm text-slate-500\">SOC 2 Type II, SSO, and encryption at rest.</p>\n          </div>\n      </div>\n    </section>\n  );\n}\n","components/Testimonial.tsx":"export default function Testimonial() {\n  return (\n    <section className=\"mx-auto max-w-3xl px-6 py-20 text-center\">\n      <p className=\"font-serif text-2xl font-medium leading-snug text-slate-900\">&ldquo;Northstar changed how our team works, within the first week.&rdquo;</p>\n      <div className=\"mt-6 flex items-center justify-center gap-3\">\n        <div className=\"h-10 w-10 rounded-full bg-indigo-100\" />\n        <div className=\"text-left\">\n          <p className=\"text-sm font-semibold text-slate-900\">Jordan Lee</p>\n          <p className=\"text-xs text-slate-500\">Customer</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Pricing.tsx":"import { Check } from \"lucide-react\";\n\nexport default function Pricing() {\n  return (\n    <section id=\"pricing\" className=\"mx-auto max-w-6xl px-6 py-20\">\n      <div className=\"max-w-xl\">\n        <h2 className=\"font-serif text-3xl font-bold tracking-tight text-slate-900\">Simple pricing, no surprises</h2>\n        <p className=\"mt-3 text-slate-500\">Start free. Upgrade when you're ready to scale Northstar.</p>\n      </div>\n      <div className=\"mt-10 grid gap-4 md:grid-cols-3\">\n          <div className=\"rounded-2xl border border-slate-100 p-6\">\n            \n            <p className=\"mt-3 font-semibold text-slate-900\">Starter</p>\n            <p className=\"mt-2 text-3xl font-bold text-slate-900\">$0<span className=\"text-sm font-normal text-slate-400\">/mo</span></p>\n            <ul className=\"mt-5 space-y-2 text-sm text-slate-600\">\n              <li className=\"flex items-center gap-2\"><Check size={14} className=\"text-indigo-600\" /> Up to 3 projects</li>\n              <li className=\"flex items-center gap-2\"><Check size={14} className=\"text-indigo-600\" /> Community support</li>\n              <li className=\"flex items-center gap-2\"><Check size={14} className=\"text-indigo-600\" /> 1 GB storage</li>\n            </ul>\n            <a href=\"/contact\" className=\"mt-6 block rounded-full border border-slate-200 text-slate-700 hover:border-slate-400 py-2.5 text-center text-sm font-semibold transition-colors\">Choose Starter</a>\n          </div>\n          <div className=\"rounded-2xl border border-indigo-500 shadow-lg shadow-indigo-100 p-6\">\n            <span className=\"rounded-full bg-indigo-600 px-2.5 py-0.5 text-[10px] font-semibold uppercase tracking-wider text-white\">Most popular</span>\n            <p className=\"mt-3 font-semibold text-slate-900\">Growth</p>\n            <p className=\"mt-2 text-3xl font-bold text-slate-900\">$29<span className=\"text-sm font-normal text-slate-400\">/mo</span></p>\n            <ul className=\"mt-5 space-y-2 text-sm text-slate-600\">\n              <li className=\"flex items-center gap-2\"><Check size={14} className=\"text-indigo-600\" /> Unlimited projects</li>\n              <li className=\"flex items-center gap-2\"><Check size={14} className=\"text-indigo-600\" /> Priority support</li>\n              <li className=\"flex items-center gap-2\"><Check size={14} className=\"text-indigo-600\" /> 50 GB storage</li>\n            </ul>\n            <a href=\"/contact\" className=\"mt-6 block rounded-full bg-indigo-600 text-white hover:bg-indigo-700 py-2.5 text-center text-sm font-semibold transition-colors\">Choose Growth</a>\n          </div>\n          <div className=\"rounded-2xl border border-slate-100 p-6\">\n            \n            <p className=\"mt-3 font-semibold text-slate-900\">Scale</p>\n            <p className=\"mt-2 text-3xl font-bold text-slate-900\">$99<span className=\"text-sm font-normal text-slate-400\">/mo</span></p>\n            <ul className=\"mt-5 space-y-2 text-sm text-slate-600\">\n              <li className=\"flex items-center gap-2\"><Check size={14} className=\"text-indigo-600\" /> Everything in Growth</li>\n              <li className=\"flex items-center gap-2\"><Check size={14} className=\"text-indigo-600\" /> SSO & audit logs</li>\n              <li className=\"flex items-center gap-2\"><Check size={14} className=\"text-indigo-600\" /> Dedicated support</li>\n            </ul>\n            <a href=\"/contact\" className=\"mt-6 block rounded-full border border-slate-200 text-slate-700 hover:border-slate-400 py-2.5 text-center text-sm font-semibold transition-colors\">Choose Scale</a>\n          </div>\n      </div>\n    </section>\n  );\n}\n"},"pages":[{"slug":"index","path":"/","name":"Home","sections":["Navbar","Hero","Stats","Features","Testimonial","Footer"]},{"slug":"pricing","path":"/pricing","name":"Pricing","sections":["Navbar","Pricing","Footer"]},{"slug":"contact","path":"/contact","name":"Contact","sections":["Navbar","ContactForm","Footer"]}]}$tpl$::jsonb),
