   <p>&copy; {new Date().getFullYear()} Ashcroft & Partners. All rights reserved.</p>\n          <div className=\"flex items-center gap-2 text-yellow-600\">\n            <span className=\"h-1.5 w-1.5 rounded-full bg-yellow-600\" /> Built with webma\n          </div>\n        </div>\n      </div>\n    </footer>\n  );\n}\n","components/ContactForm.tsx":"export default function ContactForm() {\n  return (\n    <section className=\"mx-auto max-w-2xl px-6 py-20\">\n      <h2 className=\"font-sans text-3xl font-bold tracking-tight text-slate-900\">Talk to Ashcroft & Partners</h2>\n      <p className=\"mt-3 text-slate-500\">We usually reply within a few hours.</p>\n      <form\n        className=\"mt-8 space-y-4\"\n        onSubmit={async (e) => {\n          e.preventDefault();\n          const form = e.currentTarget;\n          const data = Object.fromEntries(new FormData(form).entries());\n          const website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}\n      >\n        <div className=\"grid gap-4 sm:grid-cols-2\">\n          <input name=\"name\" required placeholder=\"Your name\" className=\"rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-yellow-500 focus:outline-none\" />\n          <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-yellow-500 focus:outline-none\" />\n        </div>\n        <textarea name=\"message\" required rows={4} placeholder=\"How can we help?\" className=\"w-full rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-yellow-500 focus:outline-none\" />\n        <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n        <button type=\"submit\" className=\"rounded-full bg-yellow-600 px-6 py-2.5 text-sm font-semibold text-white hover:bg-yellow-700 transition-colors\">Send message</button>\n      </form>\n    </section>\n  );\n}\n","components/Features.tsx":"import { Camera, Home, Briefcase, BookOpen } from \"lucide-react\";\n\nexport default function Features() {\n  return (\n    <section id=\"features\" className=\"mx-auto max-w-6xl px-6 py-20\">\n      <div className=\"max-w-xl\">\n        <h2 className=\"font-sans text-3xl font-bold tracking-tight text-slate-900\">Services</h2>\n        <p className=\"mt-3 text-slate-500\">Ashcroft brings rigor to the calls that are too important to get wrong.</p>\n      </div>\n      <div className=\"mt-10 grid gap-4 sm:grid-cols-2 lg:grid-cols-3\">\n          <div className=\"rounded-2xl border border-slate-100 p-6\">\n            <div className=\"flex h-10 w-10 items-center justify-center rounded-xl bg-yellow-100 text-yellow-600\">\n              <Camera size={18} />\n            </div>\n            <h3 className=\"mt-4 font-semibold text-slate-900\">Strategy</h3>\n            <p className=\"mt-1.5 text-sm text-slate-500\">Market analysis, competitive positioning, and growth planning.</p>\n          </div>\n          <div className=\"rounded-2xl border border-slate-100 p-6\">\n            <div className=\"flex h-10 w-10 items-center justify-center rounded-xl bg-yellow-100 text-yellow-600\">\n              <Home size={18} />\n            </div>\n            <h3 className=\"mt-4 font-semibold text-slate-900\">Operations</h3>\n            <p className=\"mt-1.5 text-sm text-slate-500\">Process redesign that actually survives contact with reality.</p>\n          </div>\n          <div className=\"rounded-2xl border border-slate-100 p-6\">\n            <div className=\"flex h-10 w-10 items-center justify-center rounded-xl bg-yellow-100 text-yellow-600\">\n              <Briefcase size={18} />\n            </div>\n            <h3 className=\"mt-4 font-semibold text-slate-900\">Change management</h3>\n            <p className=\"mt-1.5 text-sm text-slate-500\">Getting your team aligned behind the plan, not just informed of it.</p>\n          </div>\n          <div className=\"rounded-2xl border border-slate-100 p-6\">\n            <div className=\"flex h-10 w-10 items-center justify-center rounded-xl bg-yellow-100 text-yellow-600\">\n              <BookOpen size={18} />\n            </div>\n            <h3 className=\"mt-4 font-semibold text-slate-900\">Financial planning</h3>\n            <p className=\"mt-1.5 text-sm text-slate-500\">Budgets and forecasts leadership can actually trust.</p>\n          </div>\n          <div className=\"rounded-2xl border border-slate-100 p-6\">\n            <div className=\"flex h-10 w-10 items-center justify-center rounded-xl bg-yellow-100 text-yellow-600\">\n              <Camera size={18} />\n            </div>\n            <h3 className=\"mt-4 font-semibold text-slate-900\">Market entry</h3>\n            <p className=\"mt-1.5 text-sm text-slate-500\">Structured playbooks for entering a new region or segment.</p>\n          </div>\n          <div className=\"rounded-2xl border border-slate-100 p-6\">\n            <div className=\"flex h-10 w-10 items-center justify-center rounded-xl bg-yellow-100 text-yellow-600\">\n              <Home size={18} />\n            </div>\n            <h3 className=\"mt-4 font-semibold text-slate-900\">Risk assessment</h3>\n            <p className=\"mt-1.5 text-sm text-slate-500\">Identify what could go wrong before it does.</p>\n          </div>\n      </div>\n    </section>\n  );\n}\n","components/About.tsx":"export default function About() {\n  return (\n    <section className=\"mx-auto max-w-6xl px-6 py-20\">\n      <div className=\"grid items-center gap-12 m