v className=\"mt-12 flex flex-col items-center justify-between gap-4 border-t border-slate-200 pt-6 text-xs text-slate-400 sm:flex-row\">\n          <p>&copy; {new Date().getFullYear()} Ember & Oak. All rights reserved.</p>\n          <div className=\"flex items-center gap-2 text-fuchsia-600\">\n            <span className=\"h-1.5 w-1.5 rounded-full bg-fuchsia-600\" /> Built with webma\n          </div>\n        </div>\n      </div>\n    </footer>\n  );\n}\n","components/ContactForm.tsx":"export default function ContactForm() {\n  return (\n    <section className=\"mx-auto max-w-2xl px-6 py-20\">\n      <h2 className=\"font-sans text-3xl font-bold tracking-tight text-slate-900\">Talk to Ember & Oak</h2>\n      <p className=\"mt-3 text-slate-500\">We usually reply within a few hours.</p>\n      <form\n        className=\"mt-8 space-y-4\"\n        onSubmit={async (e) => {\n          e.preventDefault();\n          const form = e.currentTarget;\n          const data = Object.fromEntries(new FormData(form).entries());\n          const website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}\n      >\n        <div className=\"grid gap-4 sm:grid-cols-2\">\n          <input name=\"name\" required placeholder=\"Your name\" className=\"rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-fuchsia-500 focus:outline-none\" />\n          <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-fuchsia-500 focus:outline-none\" />\n        </div>\n        <textarea name=\"message\" required rows={4} placeholder=\"How can we help?\" className=\"w-full rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-fuchsia-500 focus:outline-none\" />\n        <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n        <button type=\"submit\" className=\"rounded-full bg-fuchsia-600 px-6 py-2.5 text-sm font-semibold text-white hover:bg-fuchsia-700 transition-colors\">Send message</button>\n      </form>\n    </section>\n  );\n}\n","components/Catalog.tsx":"export default function Catalog() {\n  return (\n    <section className=\"mx-auto max-w-6xl px-6 py-20\">\n      <div className=\"max-w-xl\">\n        <h2 className=\"font-sans text-3xl font-bold tracking-tight text-slate-900\">Menu</h2>\n        <p className=\"mt-3 text-slate-500\">A wood-fired kitchen serving seasonal plates built around whatever's best at the market.</p>\n      </div>\n      <div className=\"mt-10 grid gap-5 sm:grid-cols-2 lg:grid-cols-3\">\n          <div className=\"overflow-hidden rounded-2xl border border-slate-100\">\n            <div className=\"aspect-[4/3] bg-gradient-to-br from-fuchsia-100 to-fuchsia-50\" />\n            <div className=\"p-5\">\n              <div className=\"flex items-start justify-between gap-2\">\n                <h3 className=\"font-semibold text-slate-900\">Wood-fired trout</h3>\n                <span className=\"shrink-0 text-sm font-semibold text-fuchsia-600\">$28</span>\n              </div>\n              <p className=\"mt-1.5 text-sm text-slate-500\">Brown butter, capers, charred lemon.</p>\n            </div>\n          </div>\n          <div className=\"overflow-hidden rounded-2xl border border-slate-100\">\n            <div className=\"aspect-[4/3] bg-gradient-to-br from-fuchsia-100 to-fuchsia-50\" />\n            <div className=\"p-5\">\n              <div className=\"flex items-start justify-between gap-2\">\n                <h3 className=\"font-semibold text-slate-900\">Charred sourdough</h3>\n                <span className=\"shrink-0 text-sm font-semibold text-fuchsia-600\">$9</span>\n              </div>\n              <p className=\"mt-1.5 text-sm text-slate-500\">Cultured butter, sea salt, rosemary oil.</p>\n            </div>\n          </div>\n          <div className=\"overflow-hidden rounded-2xl border border-slate-100\">\n            <div className=\"aspect-[4/3] bg-gradient-to-br from-fuchsia-100 to-fuchsia-50\" />\n            <div className=\"p-5\">\n              <div className=\"flex items-start justify-between gap-2\">\n                <h3 className=\"font-semibold text-slate-900\">Roasted squash</h3>\n                <span className=\"shrink-0 text-sm font-semibold text-fuchsia-600\">$16</span>\n              </div>\n              <p className=\"mt-1.5 text-sm text-slate-500\">Whipped feta, pepitas, chili honey.</p>\n            </div>\n          </div>\n          <div className=\"overflow-hidden rounded-2xl border border-slate-100\">\n            <div className=\"aspect-[4/3] bg-gradient-to-br from-fuchsia-100 to-fuchsia-50\" />\n            <div className=\"p-5\">\n              <div className=\"flex items-start justify-between gap-2\">\n                <h3 className=\"font-semibold text-slate-900\">Dry-aged ribeye</h3>\n                <span className=\"shrink-0 text-sm font-semibold text-fuchsia-600\">$46</span>\n              </div>\n              <p className=\"mt-1.5 text-sm text-slate-500\">Bone marrow butter, market greens.</p>\n            </div>\n          </div>\n          <div className=\"overflow-hidden rounded-2xl border border-slate-100\">\n            <div className=\"aspect-[4/3] bg-gradient-to-br from-fuchsia-100 to-fuchsia-50\" />\n            <div className=\"p-5\">\n              <div className=\"flex items-start justify-between gap-2\">\n                <h3 className=\"font-semibold text-slate-900\">House pappardelle</h3>\n                <span className=\"shrink-0 text-sm font-semibold text-fuchsia-600\">$24</span>\n              </div>\n              <p className=\"mt-1.5 text-sm text-slate-500\">Braised short rib ragu, pecorino.</p>\n            </div>\n          </div>\n          <div className=\"overflow-hidden rounded-2xl border border-slate-100\">\n            <div className=\"aspect-[4/3] bg-gradient-to-br from-fuchsia-100 to-fuchsia-50\" />\n            <div className=\"p-5\">\n              <div className=\"flex items-start justify-between gap-2\">\n                <h3 className=\"font-semibold text-slate-900\">Olive oil cake</h3>\n                <span className=\"shrink-0 text-sm font-semibold text-fuchsia-600\">$11</span>\n              </div>\n              <p className=\"mt-1.5 text-sm text-slate-500\">Citrus, mascarpone, toasted almond.</p>\n            </div>\n          </div>\n      </div>\n    </section>\n  );\n}\n","components/About.tsx":"export default function About() {\n  return (\n    <section className=\"mx-auto max-w-6xl px-6 py-20\">\n      <div className=\"grid items-center gap-12 md:grid-cols-2\">\n        <div className=\"aspect-[4/3] rounded-2xl bg-gradient-to-br from-fuchsia-50 to-fuchsia-100 \" />\n        <div>\n          <h2 className=\"font-sans text-3xl font-bold tracking-tight text-slate-900\">About Ember & Oak</h2>\n          <p className=\"mt-4 text-slate-600\">A wood-fired kitchen serving seasonal plates built around whatever's best at the market.</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Testimonial.tsx":"export default function Testimonial() {\n  return (\n    <section className=\"mx-auto max-w-3xl px-6 py-20 text-center\">\n      <p className=\"font-sans text-2xl font-medium leading-snug text-slate-900\">&ldquo;Ember & Oak is exactly what they promise — nothing more, nothing less.&rdquo;</p>\n      <div className=\"mt-6 flex items-center justify-center gap-3\">\n        <div className=\"h-10 w-10 rounded-full bg-fuchsia-100\" />\n        <div className=\"text-left\">\n          <p className=\"text-sm font-semibold text-slate-900\">Nadia Farouk</p>\n          <p className=\"text-xs text-slate-500\">Guest</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/PageHeader.tsx":"export default function PageHeader() {\n  return (\n    <section className=\"border-b border-slate-100 bg-slate-50\">\n      <div className=\"mx-auto max-w-6xl px-6 py-16\">\n        <h1 className=\"font-sans text-3xl font-bold tracking-tight text-slate-900 md:text-4xl\">Menu</h1>\n        <p className=\"mt-3 max-w-xl text-slate-500\">A wood-fired kitchen serving seasonal plates built around whatever's best at the market.</p>\n      </div>\n    </section>\n  );\n}\n","components/Location.tsx":"export default function Location() {\n  return (\n    <section className=\"mx-auto max-w-6xl px-6 pb-20\">\n      <div className=\"grid gap-6 rounded-2xl border border-slate-100 p-8 md:grid-cols-2\">\n        <div>\n          <h2 className=\"text-xl font-bold text-slate-900\">Find Ember & Oak</h2>\n          <p className=\"mt-3 text-sm text-slate-600\">123 Main Street, Suite 4</p>\n          <p className=\"mt-4 text-xs font-semibold uppercase tracking-wider text-fuchsia-600\">Hours</p>\n          <p className=\"mt-1 text-sm text-slate-500\">Mon–Sat, 9:00am – 9:00pm</p>\n        </div>\n        <div className=\"aspect-[4/3] rounded-xl bg-gradient-to-br from-fuchsia-100 to-fuchsia-50\" />\n      </div>\n    </section>\n  );\n}\n"},"pages":[{"slug":"index","path":"/","name":"Home","sections":["Navbar","Hero","About","Testimonial","Footer"]},{"slug":"menu","path":"/menu","name":"Menu","sections":["Navbar","PageHeader","Catalog","Footer"]},{"slug":"contact","path":"/contact","name":"Contact","sections":["Navbar","ContactForm","Location","Footer"]}]}$tpl$::jsonb),
