  ('b538abb7-8111-4cb8-909f-3bf7dcdf9772', 'Fashion', 'Maison Verre', 'Considered pieces, not seasonal noise. A classic fashion site for Maison Verre, with 3 pages.', ARRAY['fashion', 'catalog', 'classic']::text[], 'classic', 'fashion', 'free', false, 'data:image/svg+xml;base64,', $tpl${"files":{"components/Navbar.tsx":"export default function Navbar() {\n  return (\n    <header className=\"sticky top-0 z-40 border-b border-slate-100 bg-white/80 backdrop-blur\">\n      <nav className=\"mx-auto flex max-w-6xl items-center justify-between px-6 py-4\">\n        <a href=\"/\" className=\"font-sans text-lg font-bold tracking-tight text-slate-900\">Maison Verre</a>\n        <div className=\"hidden items-center gap-8 md:flex\">\n        <a href=\"/collection\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Collection</a>\n        <a href=\"/contact\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Contact</a>\n        </div>\n        <a href=\"/contact\" className=\"rounded-full bg-orange-600 px-4 py-2 text-sm font-semibold text-white hover:bg-orange-700 transition-colors\">Get started</a>\n      </nav>\n    </header>\n  );\n}\n","components/Hero.tsx":"export default function Hero() {\n  return (\n    <section className=\"bg-white\">\n      <div className=\"mx-auto grid max-w-6xl items-center gap-12 px-6 py-24 md:grid-cols-2 md:py-32\">\n        <div>\n          <span className=\"inline-block rounded-full bg-orange-100 px-3 py-1 text-xs font-semibold uppercase tracking-wider text-orange-700\">Fashion</span>\n          <h1 className=\"font-sans mt-5 text-4xl font-bold leading-tight tracking-tight text-slate-900 md:text-5xl\">Considered pieces, not seasonal noise.</h1>\n          <p className=\"mt-5 max-w-lg text-lg text-slate-600\">Maison Verre designs a small collection twice a year — nothing rushed, nothing disposable.</p>\n          <div className=\"mt-8 flex flex-wrap gap-3\">\n            <a href=\"/contact\" className=\"rounded-full bg-orange-600 px-6 py-3 text-sm font-semibold text-white hover:bg-orange-700 transition-colors\">Get in touch</a>\n            <a href=\"#features\" className=\"rounded-full border border-slate-200 px-6 py-3 text-sm font-semibold text-slate-700 hover:border-slate-400 transition-colors\">View collection</a>\n          </div>\n        </div>\n        <div className=\"aspect-[4/3] rounded-2xl bg-gradient-to-br from-orange-100 to-orange-50 ring-1 ring-orange-100\" />\n      </div>\n    </section>\n  );\n}\n","components/Footer.tsx":"export default function Footer() {\n  return (\n    <footer className=\"border-t border-slate-100 bg-slate-50\">\n      <div className=\"mx-auto max-w-6xl px-6 py-14\">\n        <div className=\"grid grid-cols-2 gap-8 md:grid-cols-4\">\n          <div className=\"col-span-2 md:col-span-1\">\n            <p className=\"font-sans text-lg font-bold text-slate-900\">Maison Verre</p>\n            <p className=\"mt-2 max-w-xs text-sm text-slate-500\">Maison Verre designs a small collection twice a year — nothing rushed, nothing disposable.</p>\n          </div>\n          <div>\n            <p className=\"text-xs font-semibold uppercase tracking-wider text-slate-400\">Fashion</p>\n            <ul className=\"mt-3 space-y-2\">\n              <li><a href=\"/collection\" className=\"text-sm text-slate-500 hover:text-slate-900\">Collection</a></li>\n              <li><a href=\"/contact\" className=\"text-sm text-slate-500 hover:text-slate-900\">Contact</a></li>\n            </ul>\n          </div>\n          <div>\n            <p className=\"text-xs font-semibold uppercase tracking-wider text-slate-400\">Legal</p>\n            <ul className=\"mt-3 space-y-2\">\n              <li><a href=\"/\" className=\"text-sm text-slate-500 hover:text-slate-900\">Privacy</a></li>\n              <li><a href=\"/\" className=\"text-sm text-slate-500 hover:text-slate-900\">Terms</a></li>\n            </ul>\n          </div>\n        </div>\n        <div className=\"mt-12 flex flex-col items-center justify-between gap-4 border-t border-slate-200 pt-6 text-xs text-slate-400 sm:flex-row\">\n          <p>&copy; {new Date().getFullYear()} Maison Verre. All rights reserved.</p>\n          <div className=\"flex items-center gap-2 text-orange-600\">\n            <span className=\"h-1.5 w-1.5 rounded-full bg-orange-600\" /> Built with webma\n          </div>\n        </div>\n      </div>\n    </footer>\n  );\n}\n","components/ContactForm.tsx":"export default function ContactForm() {\n  return (\n    <section className=\"mx-auto max-w-2xl px-6 py-20\">\n      <h2 className=\"font-sans text-3xl font-bold tracking-tight text-slate-900\">Talk to Maison Verre</h2>\n      <p className=\"mt-3 text-slate-500\">We usually reply within a few hours.</p>\n      <form\n        className=\"mt-8 space-y-4\"\n        onSubmit={async (e) => {\n          e.preventDefault();\n          const form = e.currentTarget;\n          const data = Object.fromEntries(new FormData(form).entries());\n          const website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}\n      >\n        <div className=\"grid gap-4 sm:grid-cols-2\">\n          <input name=\"name\" required placeholder=\"Your name\" className=\"rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-orange-500 focus:outline-none\" />\n          <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-orange-500 focus:outline-none\" />\n        </div>\n        <textarea name=\"message\" required rows={4} placeholder=\"How can we help?\" className=\"w-full rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-orange-500 focus:outline-none\" />\n        <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n        <button type=\"submit\" className=\"rounded-full bg-orange-600 px-6 py-2.5 text-sm font-semibold text-white hover:bg-orange-700 transition-colors\">Send message</button>\n      </form>\n    </section>\n  );\n}\n","components/Catalog.tsx":"export default function Catalog() {\n  return (\n    <section className=\"mx-auto max-w-6xl px-6 py-20\">\n      <div className=\"max-w-xl\">\n        <h2 className=\"font-sans text-3xl font-bold tracking-tight text-slate-900\">Collection</h2>\n        <p className=\"mt-3 text-slate-500\">Maison Verre designs a small collection twice a year — nothing rushed, nothing disposable.</p>\n      </div>\n      <div className=\"mt-10 grid gap-5 sm:grid-cols-2 lg:grid-cols-3\">\n          <div className=\"overflow-hidden rounded-2xl border border-slate-100\">\n            <div className=\"aspect-[4/3] bg-gradient-to-br from-orange-100 to-orange-50\" />\n            <div className=\"p-5\">\n              <div className=\"flex items-start justify-between gap-2\">\n                <h3 className=\"font-semibold text-slate-900\">Tailored Blazer</h3>\n                <span className=\"shrink-0 text-sm font-semibold text-orange-600\">$340</span>\n              </div>\n              <p className=\"mt-1.5 text-sm text-slate-500\">Structured shoulder, Italian wool.</p>\n            </div>\n          </div>\n          <div className=\"overflow-hidden rounded-2xl border border-slate-100\">\n            <div className=\"aspect-[4/3] bg-gradient-to-br from-orange-100 to-orange-50\" />\n            <div className=\"p-5\">\n              <div className=\"flex items-start justify-between gap-2\">\n                <h3 className=\"font-semibold text-slate-900\">Silk Slip Dress</h3>\n                <span className=\"shrink-0 text-sm font-semibold text-orange-600\">$260</span>\n              </div>\n              <p className=\"mt-1.5 text-sm text-slate-500\">Bias-cut, hand-finished hem.</p>\n            </div>\n          </div>\n          <div className=\"overflow-hidden rounded-2xl border border-slate-100\">\n            <div className=\"aspect-[4/3] bg-gradient-to-br from-orange-100 to-orange-50\" />\n            <div className=\"p-5\">\n              <div className=\"flex items-start justify-between gap-2\">\n                <h3 className=\"font-semibold text-slate-900\">Leather Ankle Boot</h3>\n                <span className=\"shrink-0 text-sm font-semibold text-orange-600\">$310</span>\n              </div>\n              <p className=\"mt-1.5 text-sm text-slate-500\">Full-grain leather, stacked heel.</p>\n            </div>\n          </div>\n          <div className=\"overflow-hidden rounded-2xl border border-slate-100\">\n            <div className=\"aspect-[4/3] bg-gradient-to-br from-orange-100 to-orange-50\" />\n            <div className=\"p-5\">\n              <div className=\"flex items-start justify-between gap-2\">\n                <h3 className=\"font-semibold text-slate-900\">Cashmere Scarf</h3>\n                <span className=\"shrink-0 text-sm font-semibold text-orange-600\">$140</span>\n              </div>\n              <p className=\"mt-1.5 text-sm text-slate-500\">Two-ply cashmere, hand-rolled edge.</p>\n            </div>\n          </div>\n      </div>\n    </section>\n  );\n}\n","components/About.tsx":"export default function About() {\n  return (\n    <section className=\"mx-auto max-w-6xl px-6 py-20\">\n      <div className=\"grid items-center gap-12 md:grid-cols-2\">\n        <div className=\"aspect-[4/3] rounded-2xl bg-gradient-to-br from-orange-50 to-orange-100 \" />\n        <div>\n          <h2 className=\"font-sans text-3xl font-bold tracking-tight text-slate-900\">