  ('ec551d18-da79-453e-b09b-fbf3ca8e3b32', 'Architecture', 'Holt Architecture', 'Buildings that respond to how people actually live. A editorial architecture site for Holt Architecture, with 3 pages.', ARRAY['architecture', 'service', 'editorial']::text[], 'editorial', 'architecture', 'pro', false, 'data:image/svg+xml;base64,', $tpl${"files":{"components/Navbar.tsx":"export default function Navbar() {\n  return (\n    <header className=\"sticky top-0 z-40 border-b border-slate-100 bg-white/80 backdrop-blur\">\n      <nav className=\"mx-auto flex max-w-6xl items-center justify-between px-6 py-4\">\n        <a href=\"/\" className=\"font-serif text-lg font-bold tracking-tight text-slate-900\">Holt Architecture</a>\n        <div className=\"hidden items-center gap-8 md:flex\">\n        <a href=\"/work\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Work</a>\n        <a href=\"/contact\" className=\"text-sm text-slate-600 hover:text-slate-900 transition-colors\">Contact</a>\n        </div>\n        <a href=\"/contact\" className=\"rounded-full bg-blue-600 px-4 py-2 text-sm font-semibold text-white hover:bg-blue-700 transition-colors\">Get started</a>\n      </nav>\n    </header>\n  );\n}\n","components/Hero.tsx":"export default function Hero() {\n  return (\n    <section className=\"bg-white\">\n      <div className=\"mx-auto grid max-w-6xl items-center gap-12 px-6 py-24 md:grid-cols-2 md:py-32\">\n        <div>\n          <span className=\"inline-block rounded-full bg-blue-100 px-3 py-1 text-xs font-semibold uppercase tracking-wider text-blue-700\">Architecture</span>\n          <h1 className=\"font-serif mt-5 text-4xl font-bold leading-tight tracking-tight text-slate-900 md:text-5xl\">Buildings that respond to how people actually live.</h1>\n          <p className=\"mt-5 max-w-lg text-lg text-slate-600\">Holt designs from the inside out — function first, form following closely behind.</p>\n          <div className=\"mt-8 flex flex-wrap gap-3\">\n            <a href=\"/contact\" className=\"rounded-full bg-blue-600 px-6 py-3 text-sm font-semibold text-white hover:bg-blue-700 transition-colors\">Get started</a>\n            <a href=\"#features\" className=\"rounded-full border border-slate-200 px-6 py-3 text-sm font-semibold text-slate-700 hover:border-slate-400 transition-colors\">View work</a>\n          </div>\n        </div>\n        <div className=\"aspect-[4/3] rounded-2xl bg-gradient-to-br from-blue-100 to-blue-50 ring-1 ring-blue-100\" />\n      </div>\n    </section>\n  );\n}\n","components/Footer.tsx":"export default function Footer() {\n  return (\n    <footer className=\"border-t border-slate-100 bg-slate-50\">\n      <div className=\"mx-auto max-w-6xl px-6 py-14\">\n        <div className=\"grid grid-cols-2 gap-8 md:grid-cols-4\">\n          <div className=\"col-span-2 md:col-span-1\">\n            <p className=\"font-serif text-lg font-bold text-slate-900\">Holt Architecture</p>\n            <p className=\"mt-2 max-w-xs text-sm text-slate-500\">Holt designs from the inside out — function first, form following closely behind.</p>\n          </div>\n          <div>\n            <p className=\"text-xs font-semibold uppercase tracking-wider text-slate-400\">Architecture</p>\n            <ul className=\"mt-3 space-y-2\">\n              <li><a href=\"/work\" className=\"text-sm text-slate-500 hover:text-slate-900\">Work</a></li>\n              <li><a href=\"/contact\" className=\"text-sm text-slate-500 hover:text-slate-900\">Contact</a></li>\n            </ul>\n          </div>\n          <div>\n            <p className=\"text-xs font-semibold uppercase tracking-wider text-slate-400\">Legal</p>\n            <ul className=\"mt-3 space-y-2\">\n              <li><a href=\"/\" className=\"text-sm text-slate-500 hover:text-slate-900\">Privacy</a></li>\n              <li><a href=\"/\" className=\"text-sm text-slate-500 hover:text-slate-900\">Terms</a></li>\n            </ul>\n          </div>\n        </div>\n        <div className=\"mt-12 flex flex-col items-center justify-between gap-4 border-t border-slate-200 pt-6 text-xs text-slate-400 sm:flex-row\">\n          <p>&copy; {new Date().getFullYear()} Holt Architecture. All rights reserved.</p>\n          <div className=\"flex items-center gap-2 text-blue-600\">\n            <span className=\"h-1.5 w-1.5 rounded-full bg-blue-600\" /> Built with webma\n          </div>\n        </div>\n      </div>\n    </footer>\n  );\n}\n","components/ContactForm.tsx":"export default function ContactForm() {\n  return (\n    <section className=\"mx-auto max-w-2xl px-6 py-20\">\n      <h2 className=\"font-serif text-3xl font-bold tracking-tight text-slate-900\">Talk to Holt Architecture</h2>\n      <p className=\"mt-3 text-slate-500\">We usually reply within a few hours.</p>\n      <form\n        className=\"mt-8 space-y-4\"\n        onSubmit={async (e) => {\n          e.preventDefault();\n          const form = e.currentTarget;\n          const data = Object.fromEntries(new FormData(form).entries());\n          const website = data.website;\n          delete data.website;\n          try {\n            await fetch(`${process.env.NEXT_PUBLIC_APP_URL}/api/public/forms/submit`, {\n              method: \"POST\",\n              headers: { \"Content-Type\": \"application/json\" },\n              body: JSON.stringify({ projectId: \"__WEBMA_PROJECT_ID__\", formName: \"contact\", data, website }),\n            });\n            form.reset();\n          } catch (err) {}\n        }}\n      >\n        <div className=\"grid gap-4 sm:grid-cols-2\">\n          <input name=\"name\" required placeholder=\"Your name\" className=\"rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-blue-500 focus:outline-none\" />\n          <input name=\"email\" type=\"email\" required placeholder=\"Email address\" className=\"rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-blue-500 focus:outline-none\" />\n        </div>\n        <textarea name=\"message\" required rows={4} placeholder=\"How can we help?\" className=\"w-full rounded-lg border border-slate-200 px-4 py-2.5 text-sm focus:border-blue-500 focus:outline-none\" />\n        <input type=\"text\" name=\"website\" tabIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n        <button type=\"submit\" className=\"rounded-full bg-blue-600 px-6 py-2.5 text-sm font-semibold text-white hover:bg-blue-700 transition-colors\">Send message</button>\n      </form>\n    </section>\n  );\n}\n","components/Features.tsx":"import { Coffee, MapPin, Star, Check } from \"lucide-react\";\n\nexport default function Features() {\n  return (\n    <section id=\"features\" className=\"mx-auto max-w-6xl px-6 py-20\">\n      <div className=\"max-w-xl\">\n        <h2 className=\"font-sans text-3xl font-bold tracking-tight text-slate-900\">Work</h2>\n        <p className=\"mt-3 text-slate-500\">Holt designs from the inside out — function first, form following closely behind.</p>\n      </div>\n      <div className=\"mt-10 grid gap-4 sm:grid-cols-2 lg:grid-cols-3\">\n          <div className=\"rounded-2xl border border-slate-100 p-6\">\n            <div className=\"flex h-10 w-10 items-center justify-center rounded-xl bg-blue-100 text-blue-600\">\n              <Coffee size={18} />\n            </div>\n            <h3 className=\"mt-4 font-semibold text-slate-900\">Residential design</h3>\n            <p className=\"mt-1.5 text-sm text-slate-500\">New builds and full-home renovations.</p>\n          </div>\n          <div className=\"rounded-2xl border border-slate-100 p-6\">\n            <div className=\"flex h-10 w-10 items-center justify-center rounded-xl bg-blue-100 text-blue-600\">\n              <MapPin size={18} />\n            </div>\n            <h3 className=\"mt-4 font-semibold text-slate-900\">Commercial projects</h3>\n            <p className=\"mt-1.5 text-sm text-slate-500\">Retail, office, and mixed-use developments.</p>\n          </div>\n          <div className=\"rounded-2xl border border-slate-100 p-6\">\n            <div className=\"flex h-10 w-10 items-center justify-center rounded-xl bg-blue-100 text-blue-600\">\n              <Star size={18} />\n            </div>\n            <h3 className=\"mt-4 font-semibold text-slate-900\">Interior architecture</h3>\n            <p className=\"mt-1.5 text-sm text-slate-500\">Space planning integrated from the ground up.</p>\n          </div>\n          <div className=\"rounded-2xl border border-slate-100 p-6\">\n            <div className=\"flex h-10 w-10 items-center justify-center rounded-xl bg-blue-100 text-blue-600\">\n              <Check size={18} />\n            </div>\n            <h3 className=\"mt-4 font-semibold text-slate-900\">Sustainable design</h3>\n            <p className=\"mt-1.5 text-sm text-slate-500\">Passive-house and net-zero project experience.</p>\n          </div>\n      </div>\n    </section>\n  );\n}\n","components/About.tsx":"export default function About() {\n  return (\n    <section className=\"mx-auto max-w-6xl px-6 py-20\">\n      <div className=\"grid items-center gap-12 md:grid-cols-2\">\n        <div className=\"aspect-[4/3] rounded-2xl bg-gradient-to-br from-blue-50 to-blue-100 \" />\n        <div>\n          <h2 className=\"font-serif text-3xl font-bold tracking-tight text-slate-900\">About Holt Architecture</h2>\n          <p className=\"mt-4 text-slate-600\">Holt designs from the inside out — function first, form following closely behind.</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/Testimonial.tsx":"export default function Testimonial() {\n  return (\n    <section className=\"mx-auto max-w-3xl px-6 py-20 text-center\">\n      <p className=\"font-serif text-2xl font-medium leading-snug text-slate-900\">&ldquo;Holt Architecture delivered exactly what they said they would, on the timeline they gave us.&rdquo;</p>\n      <div className=\"mt-6 flex items-center justify-center gap-3\">\n        <div className=\"h-10 w-10 rounded-full bg-blue-100\" />\n        <div className=\"text-left\">\n          <p className=\"text-sm font-semibold text-slate-900\">Theo Kwan</p>\n          <p className=\"text-xs text-slate-500\">Customer</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/PageHeader.tsx":"export default function PageHeader() {\n  return (\n    <section className=\"border-b border-slate-100 bg-slate-50\">\n      <div className=\"mx-auto max-w-6xl px-6 py-16\">\n        <h1 className=\"font-serif text-3xl font-bold tracking-tight text-slate-900 md:text-4xl\">Work</h1>\n        <p className=\"mt-3 max-w-xl text-slate-500\">Holt designs from the inside out — function first, form following closely behind.</p>\n      </div>\n    </section>\n  );\n}\n"},"pages":[{"slug":"index","path":"/","name":"Home","sections":["Navbar","Hero","Features","About","Testimonial","Footer"]},{"slug":"work","path":"/work","name":"Work","sections":["Navbar","PageHeader","Features","Footer"]},{"slug":"contact","path":"/contact","name":"Contact","sections":["Navbar","ContactForm","Footer"]}]}$tpl$::jsonb),
