abIndex={-1} autoComplete=\"off\" className=\"sr-only\" aria-hidden=\"true\" />\n        <button type=\"submit\" className=\"rounded-full bg-lime-600 px-6 py-2.5 text-sm font-semibold text-white hover:bg-lime-700 transition-colors\">Send message</button>\n      </form>\n    </section>\n  );\n}\n","components/Work.tsx":"export default function Work() {\n  return (\n    <section className=\"mx-auto max-w-6xl px-6 py-20\">\n      <div className=\"max-w-xl\">\n        <h2 className=\"font-sans text-3xl font-bold tracking-tight text-slate-900\">Work</h2>\n        <p className=\"mt-3 text-slate-500\">Static takes on projects across disciplines, on purpose.</p>\n      </div>\n      <div className=\"mt-10 grid gap-5 sm:grid-cols-2 lg:grid-cols-3\">\n          <div className=\"overflow-hidden rounded-2xl border border-slate-100\">\n            <div className=\"aspect-[4/3] bg-gradient-to-br from-lime-100 to-lime-50\" />\n            <div className=\"p-5\">\n              <div className=\"flex items-start justify-between gap-2\">\n                <h3 className=\"font-semibold text-slate-900\">Art direction</h3>\n                \n              </div>\n              <p className=\"mt-1.5 text-sm text-slate-500\">Visual systems for campaigns and launches.</p>\n            </div>\n          </div>\n          <div className=\"overflow-hidden rounded-2xl border border-slate-100\">\n            <div className=\"aspect-[4/3] bg-gradient-to-br from-lime-100 to-lime-50\" />\n            <div className=\"p-5\">\n              <div className=\"flex items-start justify-between gap-2\">\n                <h3 className=\"font-semibold text-slate-900\">Illustration</h3>\n                \n              </div>\n              <p className=\"mt-1.5 text-sm text-slate-500\">Custom illustration for editorial and brand work.</p>\n            </div>\n          </div>\n          <div className=\"overflow-hidden rounded-2xl border border-slate-100\">\n            <div className=\"aspect-[4/3] bg-gradient-to-br from-lime-100 to-lime-50\" />\n            <div className=\"p-5\">\n              <div className=\"flex items-start justify-between gap-2\">\n                <h3 className=\"font-semibold text-slate-900\">Motion design</h3>\n                \n              </div>\n              <p className=\"mt-1.5 text-sm text-slate-500\">Animation for product, brand, and social.</p>\n            </div>\n          </div>\n          <div className=\"overflow-hidden rounded-2xl border border-slate-100\">\n            <div className=\"aspect-[4/3] bg-gradient-to-br from-lime-100 to-lime-50\" />\n            <div className=\"p-5\">\n              <div className=\"flex items-start justify-between gap-2\">\n                <h3 className=\"font-semibold text-slate-900\">Set design</h3>\n                \n              </div>\n              <p className=\"mt-1.5 text-sm text-slate-500\">Physical and styled sets for photo and video.</p>\n            </div>\n          </div>\n      </div>\n    </section>\n  );\n}\n","components/About.tsx":"export default function About() {\n  return (\n    <section className=\"mx-auto max-w-6xl px-6 py-20\">\n      <div className=\"grid items-center gap-12 md:grid-cols-2\">\n        <div className=\"aspect-[4/3] rounded-2xl bg-gradient-to-br from-lime-50 to-lime-100 md:order-2\" />\n        <div>\n          <h2 className=\"font-sans text-3xl font-bold tracking-tight text-slate-900\">About Static Collective</h2>\n          <p className=\"mt-4 text-slate-600\">Static takes on projects across disciplines, on purpose.</p>\n        </div>\n      </div>\n    </section>\n  );\n}\n","components/PageHeader.tsx":"export default function PageHeader() {\n  return (\n    <section className=\"border-b border-slate-100 bg-slate-50\">\n      <div className=\"mx-auto max-w-6xl px-6 py-16\">\n        <h1 className=\"font-sans text-3xl font-bold tracking-tight text-slate-900 md:text-4xl\">Work</h1>\n        <p className=\"mt-3 max-w-xl text-slate-500\">Static takes